-- ============================================================-- Таблица дружеских связей между пилотами-- ============================================================create table if not exists friends (  id bigint generated always as identity primary key,  requester_id uuid not null references auth.users(id) on delete cascade,  addressee_id uuid not null references auth.users(id) on delete cascade,  status text not null default 'pending' check (status in ('pending','accepted','blocked')),  created_at timestamptz not null default now(),  updated_at timestamptz not null default now(),  -- Уникальность: одна связь между двумя пользователями  unique (least(requester_id, addressee_id), greatest(requester_id, addressee_id))  );-- Индексыcreate index if not exists idx_friends_requester on friends(requester_id);create index if not exists idx_friends_addressee on friends(addressee_id);create index if not exists idx_friends_status on friends(status);-- Триггер обновления updated_atcreate or replace function update_friends_updated_at()returns trigger as $$begin  new.updated_at = now();  return new;end;$$ language plpgsql;drop trigger if exists tr_friends_updated_at on friends;create trigger tr_friends_updated_at  before update on friends  for each row execute function update_friends_updated_at();-- ============================================================-- RLS Policies-- ============================================================alter table friends enable row level security;-- Чтение: видим свои запросы и принятые дружбыcreate policy if not exists friends_select_own on friends  for select using (    auth.uid() = requester_id or auth.uid() = addressee_id  );-- Вставка: только свой запросcreate policy if not exists friends_insert_own on friends  for insert with check (auth.uid() = requester_id);-- Обновление: только адресат может принять/отклонить, либо любая сторона может заблокироватьcreate policy if not exists friends_update_own on friends  for update using (    auth.uid() = addressee_id or auth.uid() = requester_id  );-- Удаление: любая сторона может удалить связьcreate policy if not exists friends_delete_own on friends  for delete using (    auth.uid() = requester_id or auth.uid() = addressee_id  );-- ============================================================-- View: друзья с профилями-- ============================================================create or replace view friend_profiles asselect  f.id,  f.requester_id,  f.addressee_id,  f.status,  f.created_at,  f.updated_at,  case    when f.requester_id = auth.uid() then p2.cmdr_name    else p1.cmdr_name  end as friend_name,  case    when f.requester_id = auth.uid() then p2.avatar_url    else p1.avatar_url  end as friend_avatar,  case    when f.requester_id = auth.uid() then p2.id    else p1.id  end as friend_idfrom friends fleft join profiles p1 on p1.id = f.requester_idleft join profiles p2 on p2.id = f.addressee_idwhere f.status = 'accepted';-- ============================================================-- Функция: получить ID друзей пользователя-- ============================================================create or replace function get_friend_ids(user_uuid uuid)returns table(friend_id uuid) as $$begin  return query  select case    when f.requester_id = user_uuid then f.addressee_id    else f.requester_id  end  from friends f  where f.status = 'accepted'    and (f.requester_id = user_uuid or f.addressee_id = user_uuid);end;$$ language plpgsql security definer;